package net.civeira.phylax.feature.observe.observedissuecomment.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.valueobject.AuthorNameVO;

class AuthorNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of author name of observed issue comment")
  void test_author_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    AuthorNameValueHolder<Object> value = new AuthorNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.authorName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAuthorNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getAuthorName().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of author name of observed issue comment")
  void test_author_name_value_holder_assign_value_object() {
    Object holder = new Object();
    AuthorNameValueHolder<Object> value = new AuthorNameValueHolder<>(holder);
    AuthorNameVO vo = AuthorNameVO.from("one");
    Assertions.assertFalse(value.getAuthorNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.authorName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAuthorNameValue().orElseThrow());
    Assertions.assertSame(holder, value.authorName(Optional.empty()));
    Assertions.assertFalse(value.getAuthorNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.authorName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAuthorNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of author name of observed issue comment against the original")
  void test_author_name_value_holder_read() {
    Object holder = new Object();
    AuthorNameValueHolder<Object> value = new AuthorNameValueHolder<>(holder);
    AuthorNameVO vo = AuthorNameVO.from("one");
    AuthorNameVO other = AuthorNameVO.from("one");
    ObservedIssueComment original = Mockito.mock(ObservedIssueComment.class);
    Mockito.when(original.getAuthorNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAuthorName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readAuthorName(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.authorName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAuthorName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAuthorName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of author name of observed issue comment")
  void test_author_name_value_holder_unset() {
    Object holder = new Object();
    AuthorNameValueHolder<Object> value = new AuthorNameValueHolder<>(holder);
    AuthorNameVO vo = AuthorNameVO.from("one");
    value.authorName(vo);
    Assertions.assertSame(holder, value.unsetAuthorNameIfMatches("authorName_other"));
    Assertions.assertTrue(value.getAuthorNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAuthorNameIfMatches("authorName"));
    Assertions.assertFalse(value.getAuthorNameValue().isPresent(),
        "The field name must clear the value");
    value.authorName(vo);
    Assertions.assertSame(holder, value.unsetAuthorName());
    Assertions.assertFalse(value.getAuthorNameValue().isPresent(), "Unset must clear the value");
  }
}
